import{_ as i,a0 as r,w as l,s,ao as c,I as a,x as t,a1 as o,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在 Linux 中用 nmcli 命令绑定多块网卡 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中用 nmcli 命令绑定多块网卡 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中用 nmcli 命令绑定多块网卡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中用 nmcli 命令绑定多块网卡 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150108 Interface (NICs) Bonding in Linux using nmcli","title":"在 Linux 中用 nmcli 命令绑定多块网卡","tag":"201505","desc":""},"relativePath":"201505/20150108 Interface (NICs) Bonding in Linux using nmcli.md","filePath":"[post].md"}'),m={name:"201505/20150108 Interface (NICs) Bonding in Linux using nmcli.md"};function d(g,n,u,x,h,f){const e=r("Link");return l(),s("div",null,[n[13]||(n[13]=c(`<h1 id="在-linux-中用-nmcli-命令绑定多块网卡" tabindex="-1">在 Linux 中用 nmcli 命令绑定多块网卡 <a class="header-anchor" href="#在-linux-中用-nmcli-命令绑定多块网卡" aria-label="Permalink to “在 Linux 中用 nmcli 命令绑定多块网卡”">​</a></h1><p>今天，我们来学习一下在 CentOS 7.x 中如何用 nmcli（Network Manager Command Line Interface：网络管理命令行接口）进行网卡绑定。</p><p>网卡（接口）绑定是将多块 <strong>网卡</strong> 逻辑地连接到一起从而允许故障转移或者提高吞吐率的方法。提高服务器网络可用性的一个方式是使用多个网卡。Linux 绑定驱动程序提供了一种将多个网卡聚合到一个逻辑的绑定接口的方法。这是个新的实现绑定的方法，并不影响 linux 内核中旧绑定驱动。</p><p><strong>网卡绑定为我们提供了两个主要的好处:</strong></p><ol><li><strong>高带宽</strong></li><li><strong>冗余/弹性</strong></li></ol><p>现在让我们在 CentOS 7 上配置网卡绑定吧。我们需要决定选取哪些接口配置成一个组接口（Team interface）。</p><p>运行 <strong>ip link</strong> 命令查看系统中可用的接口。</p><pre><code> $ ip link
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/ip-link.png" alt="ip link"></p><p>这里我们使用 <strong>eno16777736</strong> 和 <strong>eno33554960</strong> 网卡在 “主动备份” 模式下创建一个组接口。(译者注：关于不同模式可以参考：<a href="http://support.huawei.com/ecommunity/bbs/10155553.html">多网卡的7种bond模式原理</a>)</p><p>按照下面的语法，用 <strong>nmcli</strong> 命令为网络组接口创建一个连接。</p><pre><code># nmcli con add type team con-name CNAME ifname INAME [config JSON]
</code></pre><p><strong>CNAME</strong> 指代连接的名称，<strong>INAME</strong> 是接口名称，<strong>JSON</strong> (JavaScript Object Notation) 指定所使用的处理器(runner)。<strong>JSON</strong> 语法格式如下：</p><pre><code>&#39;{&quot;runner&quot;:{&quot;name&quot;:&quot;METHOD&quot;}}&#39; 
</code></pre><p><strong>METHOD</strong> 是以下的其中一个：<strong>broadcast、activebackup、roundrobin、loadbalance</strong> 或者 <strong>lacp</strong>。</p><h3 id="_1-创建组接口" tabindex="-1">1. 创建组接口 <a class="header-anchor" href="#_1-创建组接口" aria-label="Permalink to “1. 创建组接口”">​</a></h3><p>现在让我们来创建组接口。这是我们创建组接口所使用的命令。</p><pre><code> # nmcli con add type team con-name team0 ifname team0 config &#39;{&quot;runner&quot;:{&quot;name&quot;:&quot;activebackup&quot;}}&#39;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nmcli-con-create.png" alt="nmcli con create"></p><p>运行 <strong># nmcli con show</strong> 命令验证组接口配置。</p><pre><code># nmcli con show
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/show-team-interface.png" alt="显示组接口"></p><h3 id="_2-添加从设备" tabindex="-1">2. 添加从设备 <a class="header-anchor" href="#_2-添加从设备" aria-label="Permalink to “2. 添加从设备”">​</a></h3><p>现在让我们添加从设备到主设备 team0。这是添加从设备的语法：</p><pre><code># nmcli con add type team-slave con-name CNAME ifname INAME master TEAM
</code></pre><p>在这里我们添加 <strong>eno16777736</strong> 和 <strong>eno33554960</strong> 作为 <strong>team0</strong> 接口的从设备。</p><pre><code># nmcli con add type team-slave con-name team0-port1 ifname eno16777736 master team0

# nmcli con add type team-slave con-name team0-port2 ifname eno33554960 master team0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/adding-to-team.png" alt="添加从设备到 team"></p><p>再次用命令 <strong>#nmcli con show</strong> 验证连接配置。现在我们可以看到从设备配置信息。</p><pre><code>#nmcli con show
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/show-slave-config.png" alt="显示从设备配置"></p><h3 id="_3-分配-ip-地址" tabindex="-1">3. 分配 IP 地址 <a class="header-anchor" href="#_3-分配-ip-地址" aria-label="Permalink to “3. 分配 IP 地址”">​</a></h3><p>上面的命令会在 <strong>/etc/sysconfig/network-scripts/</strong> 目录下创建需要的配置文件。</p><p>现在让我们为 team0 接口分配一个 IP 地址并启用这个连接。这是进行 IP 分配的命令。</p><pre><code># nmcli con mod team0 ipv4.addresses &quot;192.168.1.24/24 192.168.1.1&quot;
# nmcli con mod team0 ipv4.method manual
# nmcli con up team0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/ip-assignment.png" alt="分配 ip"></p><h3 id="_4-验证绑定" tabindex="-1">4. 验证绑定 <a class="header-anchor" href="#_4-验证绑定" aria-label="Permalink to “4. 验证绑定”">​</a></h3><p>用 <strong>#ip add show team0</strong> 命令验证 IP 地址信息。</p><pre><code>#ip add show team0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/verfiy-ip-adress.png" alt="验证 ip 地址"></p><p>现在用 <strong>teamdctl</strong> 命令检查 <strong>主动备份</strong> 配置功能。</p><pre><code># teamdctl team0 state
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/teamdctl-activebackup-check.png" alt="teamdctl 检查主动备份"></p><p>现在让我们把激活的端口断开连接并再次检查状态来确认主动备份配置是否像希望的那样工作。</p><pre><code># nmcli dev dis eno33554960
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/disconnect-activeport.png" alt="断开激活端口连接"></p><p>断开激活端口后再次用命令 <strong>#teamdctl team0 state</strong> 检查状态。</p><pre><code># teamdctl team0 state
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/teamdctl-check-activeport-disconnect.png" alt="teamdctl 检查断开激活端口连接"></p><p>是的，它运行良好！！我们会使用下面的命令连接回到 team0 的断开的连接。</p><pre><code>#nmcli dev con eno33554960
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nmcli-dev-connect-disconected.png" alt="nmcli dev 连接断开的连接"></p><p>我们还有一个 <strong>teamnl</strong> 命令可以显示 <strong>teamnl</strong> 命令的一些选项。</p><p>用下面的命令检查在 team0 运行的端口。</p><pre><code># teamnl team0 ports
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/teamnl-check-ports.png" alt="teamnl 检查端口"></p><p>显示 <strong>team0</strong> 当前活动的端口。</p><pre><code># teamnl team0 getoption activeport
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/display-active-port-team0.png" alt="显示 team0 活动端口"></p><p>好了，我们已经成功地配置了网卡绑定 😃 ，如果有任何反馈，请告诉我们。</p><hr>`,61)),a("p",null,[n[1]||(n[1]=t("via: ",-1)),o(e,{href:"http://linoxide.com/linux-command/interface-nics-bonding-linux/"},{default:p(()=>[...n[0]||(n[0]=[t("http://linoxide.com/linux-command/interface-nics-bonding-linux/",-1)])]),_:1})]),a("p",null,[n[5]||(n[5]=t("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...n[2]||(n[2]=[t("Arun Pyasi",-1)])]),_:1}),n[6]||(n[6]=t(" 译者：",-1)),o(e,{href:"https://github.com/ictlyh"},{default:p(()=>[...n[3]||(n[3]=[t("ictlyh",-1)])]),_:1}),n[7]||(n[7]=t(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:p(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),a("p",null,[n[10]||(n[10]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:p(()=>[...n[9]||(n[9]=[t("Linux中国",-1)])]),_:1}),n[12]||(n[12]=t(" 荣誉推出",-1))])])}const C=i(m,[["render",d]]);export{T as __pageData,C as default};
